select

from sh_idle_item
where (idle_name LIKE "%"#{findValue}"%" or idle_details LIKE "%"#{findValue}"%") and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_label = #{idleLabel}  and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_status = #{status} order by id desc limit #{begin}, #{nums}

